171	def aktogay() -> Params:
172	    """Масштаб реального рудника Актогай (KAZ Minerals, обл. Абай).
173	
174	    SRC: KAZ Minerals, Annual Report 2024 — переработано 58,3 Мт руды
175	    (Сульфидная‑1 28,7 Мт + Сульфидная‑2 29,6 Мт), содержание 0,43 %,
176	    извлечение 87,9 %, 221 кт меди; электроэнергия 7,32 ПДж ≈ 2 030 ГВт·ч
177	    (≈ 230 МВт в среднем, ≈ 35 кВт·ч/т).
178	    Две фабрики моделируются как две линии по ~3 330 т/ч.
179	    ВЭС, СЭС, накопитель и электросамосвалы на Актогае пока НЕТ — это
180	    ASSUMPTION (сценарий «Тыныс»), их размеры — ручки what-if.
181	    """
182	    return Params(
183	        geomet=True, flexible_maintenance=True,
184	        lat=46.95, lon=79.86,                              # SRC: координаты карьера
185	        cu_grade={"soft": 0.0042, "hard": 0.0044},          # SRC: среднее 0,43 %
186	        r150={"soft": 0.885, "hard": 0.875},                # SRC: факт 87,9 % (калибровка)
187	        line_q_nom=3330.0, line_q_min=1665.0, line_q_max=4000.0,
188	        line_p_max_mw=65.0,
189	        restart_cost_kzt=2.0e7,
190	        crush_kwh_t=0.6,
191	        # ASSUMPTION/калибровка: вспомогательные потребители (водовод с Балхаша, насосы,
192	        # хвостовое хозяйство, фильтрация, мастерские, посёлок) при номинальных потоках.
193	        # 83 МВт подобраны так, чтобы V0 без ВИЭ на погоде 2024 брал из сети ≈ 2 030 ГВт·ч
194	        # в год, как в отчёте (с постоянной частью мощности мельниц и ремонтами); regress.py.
195	        auxiliary_nominal_mw=83.0,
196	        pile_cap_t=200_000.0,
197	        mine_ore_tph=6700.0, strip_ratio=1.2,
198	        n_trucks=42, charger_n=12,
199	        wind_mw=300.0, pv_mwp=250.0,
200	        bess_mw=60.0, bess_mwh=120.0,
201	        grid_cap_mw=260.0,                                   # ASSUMPTION: предел присоединения 220 кВ (выше средней нагрузки 230 МВт)
202	    )
  1	"""GeoMet v4 spatial analogue. No claim that these are Aktogay drillholes.
  2	
  3	Measured comminution tests define 60 representative locations, NOT reserve
  4	blocks. Nearest spatial assays supply chemistry/LCT, with distances retained.
  5	Mining sequence, support volumes and LCT at P80=150 are explicit assumptions.
  6	"""
  7	from functools import lru_cache
  8	from pathlib import Path
  9	import hashlib
 10	import json
 11	import numpy as np
 12	import pandas as pd
 13	from scipy.spatial import cKDTree
 14	
 15	SOURCE = "https://doi.org/10.5281/zenodo.7051975"
 16	DATA = Path(__file__).resolve().parents[1] / "data" / "geomet"
 17	
 18	
 19	def bond_work_index(frame):
 20	    # Hoffimann et al. 2022, equation 12; M g/rev, A/F80/P80 micrometres.
 21	    return 49.0 / (frame.A**.23 * frame.M**.82 * (10/np.sqrt(frame.P80)-10/np.sqrt(frame.F80)))
 22	
 23	
 24	@lru_cache(maxsize=1)
 25	def model():
 26	    meta = json.loads((DATA / "source.json").read_text(encoding="utf-8"))
 27	    for f in meta["files"]:
 28	        digest = hashlib.md5((DATA/f["key"]).read_bytes()).hexdigest()
 29	        if f["checksum"] != "md5:"+digest:
 30	            raise ValueError("GeoMet checksum mismatch: " + f["key"])
 31	    c = pd.read_csv(DATA/"comminution.csv")
 32	    d = pd.read_csv(DATA/"drillholes.csv").dropna(subset=["X", "Y", "Z", "Cu ppm"])
 33	    f = pd.read_csv(DATA/"flotation.csv").dropna(subset=["X", "Y", "Z", "LCT"])
 34	    xyz = c[["X", "Y", "Z"]].to_numpy()
 35	    dd, di = cKDTree(d[["X", "Y", "Z"]]).query(xyz)
 36	    fd, fi = cKDTree(f[["X", "Y", "Z"]]).query(xyz)
 37	    bwi = bond_work_index(c).to_numpy()
 38	    # Preserve spatial grade contrast but calibrate the analogue's mean to
 39	    # Aktogay 0.43%; winsorize extreme assays before scaling (documented).
 40	    raw_grade = d["Cu ppm"].to_numpy()[di]/1e6
 41	    proxy = np.clip(raw_grade, *np.quantile(raw_grade, [.1, .9]))
 42	    grade = proxy/proxy.mean()*.0043
 43	    lo, hi = xyz.min(axis=0), xyz.max(axis=0)
 44	    scaled = (xyz-lo)/(hi-lo)
 45	    cells = []
 46	    for i, row in c.iterrows():
 47	        cells.append(dict(id=f"GM-{i+1:03d}", hole_id=int(row.HOLEID),
 48	            x_m=float(row.X), y_m=float(row.Y), z_m=float(row.Z),
 49	            # Schematic pit coordinates: uniform XY scaling, depth rescaling.
 50	            u=float((row.X-(lo[0]+hi[0])/2)/max(hi[:2]-lo[:2])*1.7),
 51	            v=float((row.Y-(lo[1]+hi[1])/2)/max(hi[:2]-lo[:2])*1.7),
 52	            depth=float(1-scaled[i,2]), bwi=float(bwi[i]),
 53	            grade_fraction=float(grade[i]), raw_grade_ppm=float(raw_grade[i]*1e6),
 54	            lct=float(f.iloc[fi[i]].LCT), assay_distance_m=float(dd[i]),
 55	            flotation_distance_m=float(fd[i]),
 56	            domain="hard" if bwi[i] >= np.median(bwi) else "soft"))
 57	    return dict(source=SOURCE, license="CC BY 4.0", version="GeoMet-v4",
 58	        analogue=True, method="60 comminution locations; nearest XYZ Cu and valid LCT; calibrated Cu",
 59	        drillhole_samples=len(d), comminution_samples=len(c), flotation_samples=len(f), cells=cells)
 60	
 61	
 62	def install(env):
 63	    """Deterministic two-face mining plan, 12 h per location; no random BWi."""
 64	    cells = model()["cells"]
 65	    n = env.sc.n()
 66	    env.geology_ids = {}
 67	    env.recovery_true = {}
 68	    for domain in ("soft", "hard"):
 69	        subset = sorted([c for c in cells if c["domain"] == domain], key=lambda c: (-c["z_m"], c["x_m"], c["id"]))
 70	        indices = (np.arange(n)//12 + env.sc.start_doy*2) % len(subset)
 71	        chosen = [subset[i] for i in indices]
 72	        if domain == "hard":
 73	            hard = max(subset, key=lambda c: c["bwi"])
 74	            base = env.p.hard_frac_base
 75	            for t in range(n):
 76	                base = env.sc.hard_frac_shift.get(t, base)
 77	                if base > env.p.hard_frac_base+.1:
 78	                    chosen[t] = hard
 79	        env.geology_ids[domain] = [c["id"] for c in chosen]
 80	        env.bwi_true[domain] = np.array([c["bwi"] for c in chosen])
 81	        env.grade_true[domain] = np.array([c["grade_fraction"] for c in chosen]) * env.grade_mult
 82	        env.recovery_true[domain] = np.array([c["lct"] for c in chosen])
 83	
 84	
 85	def telemetry(env, t):
 86	    if not env.p.geomet:
 87	        return {"source": "synthetic", "active_soft": "", "active_hard": ""}
 88	    out = {"source": SOURCE, "analogue": True}
 89	    for d in ("soft", "hard"):
 90	        out.update({f"active_{d}": env.geology_ids[d][t], f"bwi_{d}": float(env.bwi_true[d][t]),
 91	                    f"recovery_{d}_pct": float(env.recovery_true[d][t]*100),
 92	                    f"grade_{d}_pct": float(env.grade_true[d][t]*100)})
 93	    return out
  1	// «Тыныс 3D»: трёхмерная сцена рудника Актогай.
  2	// Данные: на стенде — живые двойники Eclipse Ditto (через прокси /ditto);
  3	// если Ditto недоступен (страница открыта отдельно) — запись 96 ч работы того же стенда (trace.json).
  4	// Масштаб схематичный: 1 ед. ≈ 10 м.
  5	import * as THREE from 'three';
